const OUTCOME_TAG=/\[\[\s*x_(success|failure)\s*\]\]/giu;const xReplyOutcomeGuidance=`Start every reply to an X mention with an outcome tag. Use [[x_success]] only when you completed the request: you answered it, or the requested work session or action actually started. Use [[x_failure]] when anything failed or blocked you, including tool or session errors, missing access, or asking the author to retry or resend. Only [[x_success]] replies are posted to X, without the tag; failure and untagged replies are withheld from X.`;function readXReplyOutcome(e){let t=`unclassified`;const n=e.replace(OUTCOME_TAG,(e,n)=>{t=t===`failure`||n.toLowerCase()===`failure`?`failure`:`success`;return``});return{outcome:t,text:n.trim()}}export{xReplyOutcomeGuidance as n,readXReplyOutcome as t};